#include "projectile/blob_detector.hpp"
#include <opencv2/imgproc.hpp>
#include <opencv2/geometry/2d.hpp>
#include <cmath>
namespace projectile { std::vector<Detection> BlobDetector::detect(const cv::Mat& mask)const{std::vector<std::vector<cv::Point>> cs;cv::findContours(mask,cs,cv::RETR_EXTERNAL,cv::CHAIN_APPROX_SIMPLE);std::vector<Detection> out;for(auto& c:cs){double a=cv::contourArea(c);if(a<1.5||a<config_.min_area||a>config_.max_area)continue;auto r=cv::boundingRect(c);double ar=std::max(r.width,r.height)/double(std::max(1,std::min(r.width,r.height)));if(ar>config_.max_aspect_ratio)continue;double p=cv::arcLength(c,true);if(p<1e-6)continue;double circ=4*CV_PI*a/(p*p);if(circ<config_.min_circularity)continue;std::vector<cv::Point> h;cv::convexHull(c,h);double sol=cv::contourArea(h)>0?a/cv::contourArea(h):0;if(sol<config_.min_solidity)continue;out.push_back({{r.x,r.y,r.width,r.height},{r.x+r.width/2.F,r.y+r.height/2.F},a,circ,sol,ar});}if(config_.isolation_filter){std::vector<bool> bad(out.size());for(size_t i=0;i<out.size();++i){int n=0;for(size_t j=0;j<out.size();++j)if(i!=j&&cv::norm(out[i].center-out[j].center)<=config_.isolation_radius)++n;if(n>=config_.isolation_min_cluster)for(size_t j=0;j<out.size();++j)if(i==j||cv::norm(out[i].center-out[j].center)<=config_.isolation_radius)bad[j]=true;}std::vector<Detection> keep;for(size_t i=0;i<out.size();++i)if(!bad[i])keep.push_back(out[i]);return keep;}return out;}}
